const query=document.querySelector('#query'),results=document.querySelector('#results'),status=document.querySelector('#status'),keyboard=document.querySelector('omni-keyboard');
const data={tabsRevision:window.omnibloomHost?null:0,tabs:[{id:'tab-fixture',title:'Reading from the couch',url:'https://example.org/reading'}],bookmarks:[{title:'Music collection',url:'https://example.org/music'},{title:'Saved reading',url:'https://example.org/reading'}],history:[{title:'Travel notes',url:'https://example.org/travel'},{title:'Local weather',url:'https://example.org/weather'}]};
let privateMode=false,optIn=false,generation=0,requestSerial=0,timer,keyboardSession=0,sourceGeneration=0,activation=0,active=true;try{optIn=localStorage.getItem('ob.searchSuggestions')==='true';}catch{}
async function request(method,params){if(window.omnibloomHost?.request){const r=await window.omnibloomHost.request({version:1,id:'address-'+(++requestSerial),method,params});if(!r?.ok)throw Error(r?.code||'OB-ADDRESS-001');return r.result;}if(method==='suggestions.search')return{queries:[params.query+' guide',params.query+' help']};window.lastAddressIntent={method,params};return{accepted:true};}
function rowKey(row){return JSON.stringify([row.kind,row.kind==='tab'?row.id:row.url||row.query]);}
function render(remote=[]){const old=[...results.querySelectorAll('button')],focused=document.activeElement,index=old.indexOf(focused),key=index>=0?focused.dataset.resultKey:null;results.replaceChildren();for(const row of OmniAddress.rank(query.value,{...data,privateMode,remote})){const b=document.createElement('button');b.type='button';b.dataset.resultKey=rowKey(row);const kind=document.createElement('span');kind.className='kind';kind.textContent={tab:'Switch to tab',bookmark:'Bookmark',history:'History',search:'Search'}[row.kind];const text=document.createElement('span'),title=document.createElement('strong'),url=document.createElement('span');title.textContent=row.title;url.className='url';url.textContent=row.url||'Search provider';text.append(title,url);b.append(kind,text);b.onclick=()=>activate(row);results.append(b);}if(!results.children.length){const empty=document.createElement('p');empty.textContent='No local matches. Press Go to search.';results.append(empty);}if(key!==null&&!document.querySelector('#address-content').hidden){const next=[...results.querySelectorAll('button')];(next.find(b=>b.dataset.resultKey===key)||next[Math.min(index,next.length-1)]||document.querySelector('#type')).focus();}}
function controls(){document.querySelector('#private').textContent='Private: '+(privateMode?'on':'off');document.querySelector('#private').setAttribute('aria-pressed',String(privateMode));document.querySelector('#remote').textContent='Search suggestions: '+(privateMode?'off in private mode':optIn?'on':'off');document.querySelector('#remote').setAttribute('aria-pressed',String(optIn&&!privateMode));document.querySelector('#remote').disabled=privateMode;document.querySelector('#privacy-note').textContent=privateMode?'Search suggestions and history are disabled in this private session.':'Turning this on sends what you type to your selected search provider.';}
async function refresh(){clearTimeout(timer);const ticket=++generation;render();if(!active||!optIn||privateMode||query.value.trim().length<2)return;const value=query.value;timer=setTimeout(async()=>{try{const result=await request('suggestions.search',{query:value,requestId:ticket});if(active&&ticket===generation&&optIn&&!privateMode&&value===query.value)render(Array.isArray(result?.queries)?result.queries:[]);}catch{if(active&&ticket===generation)status.textContent='Search suggestions unavailable. Local results still work.';}},300);}
async function activate(row){if(!active)return;const own=++activation,source=sourceGeneration;try{const action=OmniAddress.intent(row);await request(action.method,action.params);if(!active||own!==activation||source!==sourceGeneration)return;status.textContent=row.kind==='tab'?'Switch-to-tab request accepted.':row.kind==='search'?'Search request accepted.':'Open-page request accepted.';}catch(e){if(!active||own!==activation||source!==sourceGeneration)return;if(row.kind==='tab'&&e.message==='STALE_STATE'){data.tabs=[];data.tabsRevision=null;render();status.textContent='Tabs changed. Refreshing suggestions; choose a result again.';try{const next=await request('tabs.list',{});if(!active||own!==activation||source!==sourceGeneration)return;if(!validRevision(next?.revision)||!Array.isArray(next?.tabs))throw Error('INVALID_STATE');setSources(next);status.textContent='Tabs updated. Choose a result again.';}catch{if(active&&own===activation&&source===sourceGeneration)status.textContent='Tabs changed. Tab suggestions are unavailable until refreshed. Local results still work.';}return;}status.textContent='Could not open this result. Try again. '+String(e.message).replace(/[^A-Z0-9_-]/g,'').slice(0,40);}}

query.oninput=refresh;query.onkeydown=e=>{if(e.key==='Enter')document.querySelector('#go').click();};document.querySelector('#go').onclick=()=>{const value=query.value.trim();if(!value)return;if(/^[a-z][a-z0-9+.-]*:/i.test(value)&&!/^https?:/i.test(value)){status.textContent='Only HTTP and HTTPS addresses can be opened.';return;}const url=OmniAddress.url(value)||(!/\s/.test(value)&&value.includes('.')?OmniAddress.url('https://'+value):null);activate(url?{kind:'url',url}:{kind:'search',query:value});};
document.querySelector('#remote').onclick=()=>{optIn=!optIn;try{localStorage.setItem('ob.searchSuggestions',String(optIn));}catch{}controls();refresh();};document.querySelector('#private').onclick=()=>{activation++;privateMode=!privateMode;query.value='';controls();refresh();};
document.querySelector('#type').onclick=()=>{document.querySelector('#address-content').hidden=true;keyboard.show({sessionId:'address-'+(++keyboardSession),fieldId:'address',mode:'url',value:query.value,privateField:privateMode,history:privateMode?[]:data.history.map(x=>x.url),recentURLs:privateMode?[]:data.history.map(x=>x.url)});};
function closeKeyboard(){document.querySelector('#address-content').hidden=false;document.querySelector('#type').focus();}
keyboard.addEventListener('omnibloom-keyboard-commit',e=>{if(e.detail.sessionId!=='address-'+keyboardSession||e.detail.fieldId!=='address')return;query.value=e.detail.value.slice(0,512);closeKeyboard();refresh();});keyboard.addEventListener('omnibloom-keyboard-cancel',closeKeyboard);
window.omniMediaController=window.omniPadController=action=>{if(!keyboard.hidden)return keyboard.handle(action);const list=[...document.querySelectorAll('button,input')].filter(e=>!e.disabled&&e.getClientRects().length);const i=list.indexOf(document.activeElement);if(['up','down','left','right'].includes(action)){list[Math.max(0,Math.min(list.length-1,i+(['up','left'].includes(action)?-1:1)))]?.focus();document.activeElement?.scrollIntoView({block:'nearest'});return true;}if(['cross','a'].includes(action)){if(document.activeElement===query)document.querySelector('#type').click();else document.activeElement?.click();return true;}if(['circle','b'].includes(action)){query.value='';refresh();document.querySelector('#type').focus();return true;}return false;};
document.addEventListener('keydown',e=>{if(e.target===query||!keyboard.hidden)return;const action={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Escape:'circle'}[e.key];if(action&&omniPadController(action))e.preventDefault();});
function validRevision(value){return Number.isSafeInteger(value)&&value>=0;}
function setSources(value){if(!value||typeof value!=='object')return;sourceGeneration++;activation++;if(Array.isArray(value.tabs)){if(validRevision(value.revision)&&(data.tabsRevision===null||value.revision>=data.tabsRevision)){data.tabs=value.tabs.slice(0,2000);data.tabsRevision=value.revision;}else if(!validRevision(value.revision)){data.tabs=[];data.tabsRevision=null;status.textContent='Tab suggestions need a current tab revision. Local results still work.';}}for(const key of ['bookmarks','history'])if(Array.isArray(value[key]))data[key]=value[key].slice(0,2000);refresh();}
function hints(){let family='playstation';try{const stored=localStorage.getItem('ob.glyphs');if(['playstation','xbox'].includes(stored))family=stored;}catch{}try{const native=window.omnibloomHost?.getGlyphs?.();if(['playstation','xbox'].includes(native))family=native;}catch{}document.querySelector('#address-hints').textContent=(family==='xbox'?'A Select':'× Select')+' · D-pad Move · '+(family==='xbox'?'B Back':'○ Back');}
window.addEventListener('storage',e=>{if(e.key==='ob.glyphs'||e.key===null)hints();});
window.addEventListener('omnibloom-event',e=>{const type=e.detail?.event||e.detail?.type;if(['settings.changed','input.mappingChanged','glyphs.changed'].includes(type))hints();if(type==='tabs.changed')setSources(e.detail?.payload);});
window.addEventListener('pagehide',()=>{active=false;generation++;activation++;clearTimeout(timer);});
window.addEventListener('pageshow',()=>{active=true;hints();refresh();});
window.OmniAddressUI={setSources,getState:()=>({privateMode,optIn,generation,tabsRevision:data.tabsRevision})};controls();hints();render();document.querySelector('#type').focus();
